//! Subgroups of the finite quotients, given by generators (see the Python module
//! `arithkit_api.modular.subgroup` for the specification).

use std::collections::{HashMap, HashSet};

use crate::infra::arith;
use crate::infra::errors::{Error, Result};
use crate::infra::interrupt::Poll;
use crate::infra::tree::{self, Vertex};
use crate::modular::quotient::{Elem, Quotient};

/// The centre at one prime: `(p, v, w)` with `v == w` for a vertex, else the endpoints of an edge.
pub type LocalCentre = (u64, Vertex, Vertex);

/// The subgroup generated by `gens`, by breadth first search from the identity.
/// In a finite group the monoid generated by `gens` is already a group.
pub fn closure(q: &Quotient, gens: &[Elem]) -> Result<HashSet<Elem>> {
    let identity = q.identity();
    let mut seen: HashSet<Elem> = HashSet::from([identity]);
    let mut queue = vec![identity];
    let mut poll = Poll::new(1 << 10);
    while let Some(x) = queue.pop() {
        poll.tick()?;
        for g in gens {
            let y = q.mul(&x, g);
            if seen.insert(y) {
                queue.push(y);
            }
        }
    }
    Ok(seen)
}

/// A subgroup, stored by its elements in canonical order.
#[derive(Debug)]
pub struct Subgroup {
    elements: Vec<Elem>,
    set: HashSet<Elem>,
    gens: Vec<Elem>,
}

impl Subgroup {
    /// The subgroup of `q` generated by `gens` (elements of `q`).
    pub fn generated(q: &Quotient, gens: &[Elem]) -> Result<Subgroup> {
        let set = closure(q, gens)?;
        let mut elements: Vec<Elem> = set.iter().copied().collect();
        elements.sort_by_key(|x| q.sort_key(x));
        // Canonical generators: scan in canonical order, keep what is not yet generated.
        let mut kept: Vec<Elem> = Vec::new();
        let mut span: HashSet<Elem> = HashSet::from([q.identity()]);
        for x in &elements {
            if !span.contains(x) {
                kept.push(*x);
                span = closure(q, &kept)?;
            }
        }
        Ok(Subgroup {
            elements,
            set,
            gens: kept,
        })
    }

    /// The subgroup with the given elements (which must form a subgroup of `q`).
    pub fn from_elements(q: &Quotient, set: HashSet<Elem>) -> Result<Subgroup> {
        let mut elements: Vec<Elem> = set.iter().copied().collect();
        elements.sort_by_key(|x| q.sort_key(x));
        let mut kept: Vec<Elem> = Vec::new();
        let mut span: HashSet<Elem> = HashSet::from([q.identity()]);
        for x in &elements {
            if !span.contains(x) {
                kept.push(*x);
                span = closure(q, &kept)?;
            }
        }
        Ok(Subgroup {
            elements,
            set,
            gens: kept,
        })
    }

    /// The centre of `Fix(U_p)` for a prime `p | NM` (maths: sec:subgroup-classes).
    fn local_centre(&self, q: &Quotient, p: u64) -> (Vertex, Vertex) {
        let k = if q.m().is_multiple_of(p) {
            arith::factor(q.m())
                .iter()
                .find(|f| f.0 == p)
                .map_or(0, |f| f.1)
        } else {
            0
        };
        let sources = if q.n().is_multiple_of(p) {
            vec![tree::origin(), tree::standard_neighbour()]
        } else {
            vec![tree::origin()]
        };
        let matrices: Vec<_> = self.gens.iter().map(|g| q.local_matrix(g, p)).collect();
        let fixed: HashSet<Vertex> = tree::ball(p, &sources, k)
            .into_iter()
            .filter(|v| matrices.iter().all(|g| tree::fixes(p, g, v)))
            .collect();
        if fixed.is_empty() {
            // No fixed vertex: U fixes c_N, so Fix(U_p) is the midpoint of the standard edge.
            return (tree::standard_neighbour(), tree::origin());
        }
        tree::centre(p, &fixed)
    }

    /// The centre at the primes dividing `NM`, in increasing order (def:helling-level).
    pub fn centre(&self, q: &Quotient) -> Vec<LocalCentre> {
        q.primes_nm()
            .into_iter()
            .map(|p| {
                let (v, w) = self.local_centre(q, p);
                (p, v, w)
            })
            .collect()
    }

    /// The Helling level: the product of the primes with an edge midpoint as centre.
    pub fn helling_level(&self, q: &Quotient) -> u64 {
        self.centre(q)
            .iter()
            .filter(|(_, v, w)| v != w)
            .map(|(p, _, _)| *p)
            .product()
    }

    /// Whether the centre is the standard point c_N (def:centred-subgroup).
    pub fn is_centred(&self, q: &Quotient) -> bool {
        self.centre(q).iter().all(|(p, v, w)| {
            if q.n().is_multiple_of(*p) {
                *v == tree::standard_neighbour() && *w == tree::origin()
            } else {
                *v == tree::origin() && *w == tree::origin()
            }
        })
    }

    /// The least `m | M` such that the subgroup contains the kernel of the reduction to level `m`.
    pub fn principal_level(&self, q: &Quotient) -> Result<u64> {
        for m in divisors_of(q.m()) {
            if q.kernel_elements(m)?.iter().all(|x| self.contains(x)) {
                return Ok(m);
            }
        }
        unreachable!("the kernel of the reduction to level M is trivial")
    }

    /// The number of elements.
    pub fn order(&self) -> usize {
        self.elements.len()
    }

    /// The elements in canonical order.
    pub fn elements(&self) -> &[Elem] {
        &self.elements
    }

    /// The canonical generators in canonical order.
    pub fn gens(&self) -> &[Elem] {
        &self.gens
    }

    /// Whether `x` lies in the subgroup.
    pub fn contains(&self, x: &Elem) -> bool {
        self.set.contains(x)
    }

    /// Whether this subgroup is contained in `other` (same parent).
    pub fn is_subset(&self, other: &Subgroup) -> bool {
        self.elements.len() <= other.elements.len()
            && self.elements.iter().all(|x| other.contains(x))
    }

    /// The types occurring in the subgroup, in increasing order (def:al-image).
    pub fn al_image(&self, q: &Quotient) -> Vec<u64> {
        let mut types: Vec<u64> = self.set.iter().map(|x| q.type_of(x.mask)).collect();
        types.sort_unstable();
        types.dedup();
        types
    }
}

/// The positive divisors of `n`, in increasing order.
fn divisors_of(n: u64) -> Vec<u64> {
    let mut out = vec![1u64];
    for (p, k) in arith::factor(n) {
        let current = out.clone();
        let mut power = 1u64;
        for _ in 0..k {
            power *= p;
            out.extend(current.iter().map(|d| d * power));
        }
    }
    out.sort_unstable();
    out
}

/// The group as numbered elements: element `i` is the `i`-th element in canonical order.
struct Table<'a> {
    q: &'a Quotient,
    elements: Vec<Elem>,
    position: Position,
    inv: Vec<u32>,
    /// The full multiplication table (row-major), for groups of order at most `TABLE_LIMIT`.
    products: Option<Vec<u32>>,
}

/// Element numbers: a dense array indexed by the encoding (type rank, a, b, c, d) when that is
/// small, otherwise a hash map.
enum Position {
    Dense {
        rank: Vec<u64>,
        m: u64,
        slots: Vec<u32>,
    },
    Hash(HashMap<Elem, u32>),
}

/// Use the dense array when it has at most this many slots (256 MB).
const DENSE_LIMIT: u64 = 1 << 26;

impl Position {
    fn new(q: &Quotient, elements: &[Elem]) -> Position {
        let types = q.type_group();
        let m = q.m();
        let slots_needed = m
            .checked_pow(4)
            .and_then(|x| x.checked_mul(types.len() as u64));
        if let Some(size) = slots_needed.filter(|&size| size <= DENSE_LIMIT) {
            let mut rank = vec![0u64; types.len()];
            for (mask, r) in rank.iter_mut().enumerate() {
                let e = q.type_of(u32::try_from(mask).expect("small"));
                *r = types.iter().position(|&t| t == e).expect("a type") as u64;
            }
            let mut position = Position::Dense {
                rank,
                m,
                slots: vec![u32::MAX; usize::try_from(size).expect("fits")],
            };
            for (i, x) in elements.iter().enumerate() {
                let slot = position.slot(x);
                if let Position::Dense { slots, .. } = &mut position {
                    slots[slot] = u32::try_from(i).expect("group too large");
                }
            }
            position
        } else {
            Position::Hash(
                elements
                    .iter()
                    .enumerate()
                    .map(|(i, x)| (*x, u32::try_from(i).expect("group too large")))
                    .collect(),
            )
        }
    }

    fn slot(&self, x: &Elem) -> usize {
        match self {
            Position::Dense { rank, m, .. } => {
                let [a, b, c, d] = x.u;
                let key = (((rank[x.mask as usize] * m + a) * m + b) * m + c) * m + d;
                usize::try_from(key).expect("fits")
            }
            Position::Hash(_) => unreachable!("only for the dense array"),
        }
    }

    fn get(&self, x: &Elem) -> u32 {
        match self {
            Position::Dense { slots, .. } => slots[self.slot(x)],
            Position::Hash(map) => map[x],
        }
    }
}

/// Precompute all products for groups of at most this order (64 MB of table).
const TABLE_LIMIT: usize = 4096;

impl<'a> Table<'a> {
    fn new(q: &'a Quotient) -> Result<Table<'a>> {
        let elements = q.elements()?;
        let position = Position::new(q, &elements);
        let inv = elements
            .iter()
            .map(|x| position.get(&q.inverse(x)))
            .collect();
        let mut table = Table {
            q,
            elements,
            position,
            inv,
            products: None,
        };
        let n = table.elements.len();
        if n <= TABLE_LIMIT {
            let mut products = Vec::with_capacity(n * n);
            let mut poll = Poll::new(1 << 12);
            for a in 0..n {
                for b in 0..n {
                    poll.tick()?;
                    products.push(table.compute(a, b));
                }
            }
            table.products = Some(products);
        }
        Ok(table)
    }

    fn compute(&self, a: usize, b: usize) -> u32 {
        self.position
            .get(&self.q.mul(&self.elements[a], &self.elements[b]))
    }

    fn mul(&self, a: u32, b: u32) -> u32 {
        match &self.products {
            Some(products) => products[a as usize * self.elements.len() + b as usize],
            None => self.compute(a as usize, b as usize),
        }
    }

    /// The subgroup generated by `gens`, as a membership vector.
    fn closure(&self, gens: &[u32]) -> Result<Vec<bool>> {
        Ok(self.capped_closure(gens, usize::MAX)?.expect("no cap"))
    }

    /// The subgroup generated by `gens`, or `None` as soon as it has more than `cap` elements.
    fn capped_closure(&self, gens: &[u32], cap: usize) -> Result<Option<Vec<bool>>> {
        let identity = self.position.get(&self.q.identity());
        let mut seen = vec![false; self.elements.len()];
        seen[identity as usize] = true;
        let mut queue = vec![identity];
        let mut size = 1usize;
        let mut poll = Poll::new(1 << 12);
        while let Some(x) = queue.pop() {
            poll.tick()?;
            for &g in gens {
                let y = self.mul(x, g);
                if !seen[y as usize] {
                    seen[y as usize] = true;
                    size += 1;
                    if size > cap {
                        return Ok(None);
                    }
                    queue.push(y);
                }
            }
        }
        Ok(Some(seen))
    }

    /// def:canonical-generators; the canonical order is the order of the indices.
    fn canonical_generators(&self, members: &[bool]) -> Result<Vec<u32>> {
        let mut kept = Vec::new();
        let mut span = self.closure(&[])?;
        for (x, &inside) in members.iter().enumerate() {
            let x = u32::try_from(x).expect("small");
            if inside && !span[x as usize] {
                kept.push(x);
                span = self.closure(&kept)?;
            }
        }
        Ok(kept)
    }
}

/// The search state of alg:coset-tables.
/// A subgroup during the search: membership vector and list of elements.
struct Subset {
    bits: Vec<bool>,
    list: Vec<u32>,
}

impl Table<'_> {
    /// The subgroup generated by the subgroup `h` and `gens` (which must include generators of
    /// `h`), or `None` as soon as it has more than `cap` elements. Dimino's method: the result
    /// is a union of right cosets `H y`; only coset representatives are multiplied by `gens`.
    fn extend_subgroup(&self, h: &Subset, gens: &[u32], cap: usize) -> Result<Option<Subset>> {
        let mut bits = h.bits.clone();
        let mut list = h.list.clone();
        let identity = self.position.get(&self.q.identity());
        let mut reps = vec![identity];
        let mut i = 0;
        let mut poll = Poll::new(1 << 10);
        while i < reps.len() {
            let x = reps[i];
            i += 1;
            for &t in gens {
                poll.tick()?;
                let y = self.mul(x, t);
                if bits[y as usize] {
                    continue;
                }
                if list.len() + h.list.len() > cap {
                    return Ok(None);
                }
                for &z in &h.list {
                    let w = self.mul(z, y);
                    bits[w as usize] = true;
                    list.push(w);
                }
                reps.push(y);
            }
        }
        Ok(Some(Subset { bits, list }))
    }
}

struct Search<'a, 'b> {
    table: &'b Table<'a>,
    gens: Vec<u32>,
    max_index: usize,
    found: Vec<(Vec<bool>, Vec<u32>)>,
}

impl Search<'_, '_> {
    /// The cosets `r_i H` are distinct.
    fn consistent(&self, reps: &[u32], h: &[bool]) -> bool {
        (0..reps.len()).all(|i| {
            (i + 1..reps.len())
                .all(|k| !h[self.table.mul(self.table.inv[reps[i] as usize], reps[k]) as usize])
        })
    }

    fn extend(
        &mut self,
        reps: &mut Vec<u32>,
        defined: usize,
        schreier: &mut Vec<u32>,
        h: &Subset,
    ) -> Result<()> {
        crate::infra::interrupt::check()?;
        let r = self.gens.len();
        // Entries are defined in the order (0,0), (0,1), ..., so `defined` indexes the next one.
        if defined == reps.len() * r {
            if reps.len() * h.list.len() == self.table.elements.len() {
                self.found.push((h.bits.clone(), reps.clone()));
            }
            return Ok(());
        }
        let (i, j) = (defined / r, defined % r);
        let image = self.table.mul(self.gens[j], reps[i]); // s_j r_i
        // r_k^{-1} s_j r_i for the existing points k.
        let elements: Vec<u32> = reps
            .iter()
            .map(|&r| self.table.mul(self.table.inv[r as usize], image))
            .collect();
        if elements.iter().any(|&e| h.bits[e as usize]) {
            // s_j r_i lies in a known coset r_k H: the entry is forced (any other choice, or a new
            // point, would put s_j r_i into two cosets).
            return self.extend(reps, defined + 1, schreier, h);
        }
        for &element in &elements {
            schreier.push(element);
            // n distinct cosets force |H| <= |G|/n: stop the closure early when it gets larger.
            let cap = self.table.elements.len() / reps.len();
            if let Some(new_h) = self.table.extend_subgroup(h, schreier, cap)?
                && self.consistent(reps, &new_h.bits)
            {
                self.extend(reps, defined + 1, schreier, &new_h)?;
            }
            schreier.pop();
        }
        if reps.len() < self.max_index {
            reps.push(image);
            if self.consistent(reps, &h.bits) {
                self.extend(reps, defined + 1, schreier, h)?;
            }
            reps.pop();
        }
        Ok(())
    }
}

/// The index of a class and the members of its canonical representative.
type ClassEntry = (usize, Vec<bool>);

/// The canonical representatives of the conjugacy classes of subgroups of index at most
/// `max_index`, sorted by index and then by canonical generators (alg:subgroup-classes).
pub fn subgroup_classes(q: &Quotient, max_index: u64) -> Result<Vec<Subgroup>> {
    if max_index == 0 {
        return Err(Error::InvalidParameter(
            "the index bound must be at least 1".into(),
        ));
    }
    let table = Table::new(q)?;
    let all = vec![true; table.elements.len()];
    let gens = table.canonical_generators(&all)?;
    let max_index = usize::try_from(max_index)
        .unwrap_or(usize::MAX)
        .min(table.elements.len());
    let mut search = Search {
        table: &table,
        gens,
        max_index,
        found: Vec::new(),
    };
    let identity = table.position.get(&q.identity());
    let mut bits = vec![false; table.elements.len()];
    bits[identity as usize] = true;
    let trivial = Subset {
        bits,
        list: vec![identity],
    };
    search.extend(&mut vec![identity], 0, &mut Vec::new(), &trivial)?;
    let found = std::mem::take(&mut search.found);
    let mut classes: HashMap<Vec<u32>, ClassEntry> = HashMap::new();
    let mut seen: HashSet<Vec<bool>> = HashSet::new(); // subgroups whose class has been handled
    for (h, reps) in found {
        if seen.contains(&h) {
            continue;
        }
        let mut best: Option<(Vec<u32>, Vec<bool>)> = None;
        for &r in &reps {
            let mut conjugate = vec![false; table.elements.len()];
            for (x, &inside) in h.iter().enumerate() {
                if inside {
                    let x = u32::try_from(x).expect("small");
                    conjugate[table.mul(table.mul(r, x), table.inv[r as usize]) as usize] = true;
                }
            }
            if !seen.insert(conjugate.clone()) {
                continue; // a conjugate already considered for this class
            }
            let key = table.canonical_generators(&conjugate)?;
            if best.as_ref().is_none_or(|(k, _)| key < *k) {
                best = Some((key, conjugate));
            }
        }
        let (key, members) = best.expect("at least one representative");
        classes.entry(key).or_insert((reps.len(), members));
    }
    let mut ordered: Vec<(Vec<u32>, ClassEntry)> = classes.into_iter().collect();
    ordered.sort_by(|a, b| (a.1.0, &a.0).cmp(&(b.1.0, &b.0)));
    ordered
        .into_iter()
        .map(|(_, (_, members))| {
            let set = members
                .iter()
                .enumerate()
                .filter(|(_, b)| **b)
                .map(|(i, _)| table.elements[i])
                .collect();
            Subgroup::from_elements(q, set)
        })
        .collect()
}

impl PartialEq for Subgroup {
    fn eq(&self, other: &Subgroup) -> bool {
        self.elements == other.elements
    }
}

impl Eq for Subgroup {}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn class_counts_match_magma() {
        // Magma: Subgroups(G : IndexLimit := I) for GL_2(Z/n) and SL_2(Z/n).
        for (lifted, n, bound, count) in [
            (false, 2, 6, 4),
            (false, 3, 48, 16),
            (true, 3, 48, 7),
            (false, 4, 30, 54),
            (true, 4, 30, 18),
        ] {
            let q = Quotient::new(1, n, lifted).unwrap();
            assert_eq!(
                subgroup_classes(&q, bound).unwrap().len(),
                count,
                "lifted={lifted} n={n}"
            );
        }
    }

    #[test]
    fn centred_classes_of_s3() {
        let q = Quotient::new(1, 2, false).unwrap();
        let classes = subgroup_classes(&q, 6).unwrap();
        let orders: Vec<usize> = classes.iter().map(Subgroup::order).collect();
        assert_eq!(orders, vec![6, 3, 2, 1]);
        let centred: Vec<bool> = classes.iter().map(|h| h.is_centred(&q)).collect();
        assert_eq!(centred, vec![true, true, false, true]);
        assert_eq!(classes[2].helling_level(&q), 2);
        assert_eq!(classes[3].principal_level(&q).unwrap(), 2);
    }

    #[test]
    fn whole_group_and_trivial_group() {
        let q = Quotient::new(6, 4, false).unwrap();
        let all = q.elements().unwrap();
        let whole = Subgroup::generated(&q, &all).unwrap();
        assert_eq!(whole.elements(), all.as_slice());
        let regenerated = Subgroup::generated(&q, whole.gens()).unwrap();
        assert_eq!(regenerated, whole);
        assert_eq!(regenerated.gens(), whole.gens());
        let trivial = Subgroup::generated(&q, &[]).unwrap();
        assert_eq!(trivial.order(), 1);
        assert!(trivial.gens().is_empty());
        assert!(trivial.is_subset(&whole));
        assert_eq!(whole.al_image(&q), vec![1, 2, 3, 6]);
    }
}
